<div class="table-responsive"><table class="table table-hover"><thead><tr><th>#</th><th><?= _l('sccc_subject') ?></th><th><?= _l('sccc_direction') ?></th><th><?= _l('sccc_phone') ?></th><th><?= _l('sccc_status') ?></th><th><?= _l('sccc_duration') ?></th><th><?= _l('sccc_date') ?></th></tr></thead><tbody><?php foreach($calls as $c){?><tr><td><?= (int)$c['id']?></td><td><?= html_escape($c['subject']?:_l('sccc_call'))?></td><td><?= _l('sccc_'.$c['direction'])?></td><td><?= html_escape(sccc_phone_display($c['to_number']?:$c['from_number']))?></td><td><span class="label label-default"><?= html_escape($c['status'])?></span></td><td><?= (int)$c['duration']?>s</td><td><?= html_escape($c['created_at'])?></td></tr><?php }?></tbody></table></div>